        assert_eq!(CropDown::parse("off"), CropDown::OFF);
        assert_eq!(CropDown::parse("all"), CropDown::ALL);
        assert_eq!(CropDown::parse("hold, scent"), CropDown::ON);
        assert_eq!(CropDown::parse("hold,scent,keep0"), CropDown::ALL);
